#!/usr/bin/env node
/**
 * Every API route has a Bruno request, and every Bruno request points at a
 * real route. Routes come from the committed Tuyau registry
 * (`.adonisjs/client/registry/index.ts`, regenerated by `npm run codegen`);
 * requests from every `.bru` file under `bruno/`. Route parameters
 * (`:tripId`) and Bruno variables (`{{tripId}}`) both normalise to `:*`.
 *
 * Usage: node scripts/bruno-coverage.mjs   (from apps/api or the repo root)
 */
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const apiRoot = join(dirname(fileURLToPath(import.meta.url)), '..')
const registryPath = join(apiRoot, '.adonisjs/client/registry/index.ts')
const brunoRoot = join(apiRoot, 'bruno')

/** `METHOD /path` with every parameter replaced by `:*`. */
function key(method, path) {
  return `${method.toUpperCase()} ${path.replace(/:[A-Za-z0-9_]+|\{\{[^}]+\}\}/g, ':*').replace(/\/+$/, '')}`
}

function routesFromRegistry() {
  const source = readFileSync(registryPath, 'utf8')
  const routes = new Map()
  const entry = /'([^']+)':\s*\{\s*methods:\s*\[([^\]]*)\],\s*pattern:\s*'([^']+)'/g
  for (const match of source.matchAll(entry)) {
    const [, name, methods, pattern] = match
    for (const method of methods.split(',').map((m) => m.trim().replace(/"/g, ''))) {
      if (method === 'HEAD') continue
      routes.set(key(method, pattern), name)
    }
  }
  return routes
}

function bruFiles(dir) {
  return readdirSync(dir).flatMap((name) => {
    const full = join(dir, name)
    if (statSync(full).isDirectory()) return name === 'environments' ? [] : bruFiles(full)
    return name.endsWith('.bru') && name !== 'collection.bru' ? [full] : []
  })
}

function requestsFromBruno() {
  const requests = []
  for (const file of bruFiles(brunoRoot)) {
    const text = readFileSync(file, 'utf8')
    const block = text.match(/^(get|post|put|patch|delete|head|options)\s*\{[^}]*url:\s*(\S+)/m)
    if (!block) continue
    const [, method, url] = block
    const path = url.replace('{{baseUrl}}', '').replace(/\?.*$/, '')
    requests.push({ file: relative(apiRoot, file), key: key(method, path) })
  }
  return requests
}

const routes = routesFromRegistry()
const requests = requestsFromBruno()
const covered = new Set(requests.map((request) => request.key))

const missing = [...routes.entries()].filter(([routeKey]) => !covered.has(routeKey))
const orphans = requests.filter((request) => !routes.has(request.key))

for (const [routeKey, name] of missing) {
  console.error(`bruno-coverage: no request for ${name} (${routeKey})`)
}
for (const orphan of orphans) {
  console.error(`bruno-coverage: ${orphan.file} points at no route (${orphan.key})`)
}
if (routes.size === 0) {
  console.error('bruno-coverage: the registry lists no routes; run npm run codegen')
  process.exit(2)
}
if (missing.length > 0 || orphans.length > 0) {
  process.exit(1)
}
console.log(`bruno-coverage: ok, ${routes.size} routes, ${requests.length} requests`)
